package eval

func recipeCatalogSuite() Suite {
	base := shopsSuite()
	recipe := map[string]any{"recipe_id": "recipe-antitoxin", "name": "Antitoxin", "ingredients": map[string]any{"healing-potion": 2}, "output_item": "torch", "output_quantity": 1}
	return Suite{ID: "071-recipe-catalog", Name: "Campaign Play 071: Recipe Catalog", Tests: append(base.Tests,
		playTest("play-recipe-player-create-forbidden", "Players cannot create recipes", "POST", "/v1/play/campaigns/play-2/recipes", recipe, map[string]string{"Authorization": playerAAuth}, 403, nil),
		playTest("play-recipe-invalid-id", "Recipe creation requires a nonempty recipe ID", "POST", "/v1/play/campaigns/play-2/recipes", map[string]any{"recipe_id": "", "name": "Antitoxin", "ingredients": map[string]any{"healing-potion": 2}, "output_item": "torch", "output_quantity": 1}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-recipe-invalid-name", "Recipe creation requires a nonempty name", "POST", "/v1/play/campaigns/play-2/recipes", map[string]any{"recipe_id": "recipe-bad-name", "name": "", "ingredients": map[string]any{"healing-potion": 2}, "output_item": "torch", "output_quantity": 1}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-recipe-empty-ingredients", "Recipe creation requires nonempty ingredients", "POST", "/v1/play/campaigns/play-2/recipes", map[string]any{"recipe_id": "recipe-empty-ingredients", "name": "Empty", "ingredients": map[string]any{}, "output_item": "torch", "output_quantity": 1}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-recipe-invalid-ingredient-id", "Recipe ingredients require valid catalog item IDs", "POST", "/v1/play/campaigns/play-2/recipes", map[string]any{"recipe_id": "recipe-bad-ingredient", "name": "Bad Ingredient", "ingredients": map[string]any{"longsword": 1}, "output_item": "torch", "output_quantity": 1}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-recipe-invalid-ingredient-quantity", "Recipe ingredient quantities must be positive integers", "POST", "/v1/play/campaigns/play-2/recipes", map[string]any{"recipe_id": "recipe-bad-quantity", "name": "Bad Quantity", "ingredients": map[string]any{"healing-potion": 0}, "output_item": "torch", "output_quantity": 1}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-recipe-invalid-output", "Recipe output item must be in the item catalog", "POST", "/v1/play/campaigns/play-2/recipes", map[string]any{"recipe_id": "recipe-bad-output", "name": "Bad Output", "ingredients": map[string]any{"healing-potion": 2}, "output_item": "longsword", "output_quantity": 1}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-recipe-invalid-output-quantity", "Recipe output quantity must be positive", "POST", "/v1/play/campaigns/play-2/recipes", map[string]any{"recipe_id": "recipe-bad-output-quantity", "name": "Bad Output Quantity", "ingredients": map[string]any{"healing-potion": 2}, "output_item": "torch", "output_quantity": 0}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTestExactJSON("play-recipe-create-antitoxin", "DM creates a deterministic recipe", "POST", "/v1/play/campaigns/play-2/recipes", recipe, map[string]string{"Authorization": dmAuth}, 201, recipe),
		playTest("play-recipe-duplicate-id", "Duplicate recipe IDs conflict", "POST", "/v1/play/campaigns/play-2/recipes", recipe, map[string]string{"Authorization": dmAuth}, 409, nil),
		playTestExactJSON("play-recipe-list-player", "Campaign members list recipes in creation order", "GET", "/v1/play/campaigns/play-2/recipes", nil, map[string]string{"Authorization": playerAAuth}, 200, map[string]any{"recipes": []any{recipe}}),
		playTest("play-recipe-craft-dm-forbidden", "DM cannot craft recipes", "POST", "/v1/play/campaigns/play-2/recipes/recipe-antitoxin/craft", map[string]any{"character_id": "play-char-w"}, map[string]string{"Authorization": dmAuth}, 403, nil),
		playTest("play-recipe-craft-non-owner-forbidden", "Players cannot craft for another player's character", "POST", "/v1/play/campaigns/play-2/recipes/recipe-antitoxin/craft", map[string]any{"character_id": "play-char-b"}, map[string]string{"Authorization": playerAAuth}, 403, nil),
		playTest("play-recipe-craft-unknown", "Unknown recipes return 404 for craft", "POST", "/v1/play/campaigns/play-2/recipes/recipe-missing/craft", map[string]any{"character_id": "play-char-w"}, map[string]string{"Authorization": playerAAuth}, 404, nil),
		playTest("play-recipe-add-second-potion", "Public inventory API provisions the remaining recipe ingredient", "POST", "/v1/play/campaigns/play-2/characters/play-char-w/inventory/items", map[string]any{"item_id": "healing-potion", "quantity": 1}, map[string]string{"Authorization": playerAAuth}, 201, map[string]any{"character_id": "play-char-w", "item_id": "healing-potion", "quantity": 1, "total_quantity": 2}),
		playTestExactJSON("play-recipe-craft-antitoxin", "Owner crafts once by atomically consuming ingredients and adding output", "POST", "/v1/play/campaigns/play-2/recipes/recipe-antitoxin/craft", map[string]any{"character_id": "play-char-w"}, map[string]string{"Authorization": playerAAuth}, 201, map[string]any{"character_id": "play-char-w", "recipe_id": "recipe-antitoxin", "output_item": "torch", "output_quantity": 1}),
		playTestExactJSON("play-recipe-inventory-after-craft", "Crafting consumes ingredients and adds output to inventory", "GET", "/v1/play/campaigns/play-2/characters/play-char-w/inventory/items", nil, map[string]string{"Authorization": playerAAuth}, 200, map[string]any{"character_id": "play-char-w", "items": []any{map[string]any{"item_id": "amulet-of-health", "quantity": 1}, map[string]any{"item_id": "leather-armor", "quantity": 1}, map[string]any{"item_id": "ring-of-protection", "quantity": 1}, map[string]any{"item_id": "torch", "quantity": 2}}}),
		playTest("play-recipe-craft-repeat-insufficient", "Repeating craft without ingredients conflicts without mutation", "POST", "/v1/play/campaigns/play-2/recipes/recipe-antitoxin/craft", map[string]any{"character_id": "play-char-w"}, map[string]string{"Authorization": playerAAuth}, 409, nil),
		playTestExactJSON("play-recipe-inventory-after-reject", "Rejected repeat craft leaves inventory unchanged", "GET", "/v1/play/campaigns/play-2/characters/play-char-w/inventory/items", nil, map[string]string{"Authorization": playerAAuth}, 200, map[string]any{"character_id": "play-char-w", "items": []any{map[string]any{"item_id": "amulet-of-health", "quantity": 1}, map[string]any{"item_id": "leather-armor", "quantity": 1}, map[string]any{"item_id": "ring-of-protection", "quantity": 1}, map[string]any{"item_id": "torch", "quantity": 2}}}),
	)}
}
